examples.template:
HStack(spacing: theme.spacing.space1) {
    Text({{before}})
    Button({{link}}) { opened = true }
        .buttonStyle(.monarchLink(.standalone))
        .popover(isPresented: $opened) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text({{card.title}}).monarchTextStyle(.bodyStrong)
                Text({{card.summary}}).monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
                Text({{card.updated}}).monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
            }
            .foregroundStyle(theme.colors.textDefault)
            .padding(theme.spacing.space4)
            .frame(width: 280, alignment: .leading)
            .presentationCompactAdaptation(.popover)
        }
    Text({{after}})
}

examples.code:
HStack(spacing: theme.spacing.space1) {
    Text("See the")
    Button("Onboarding checklist") { opened = true }
        .buttonStyle(.monarchLink(.standalone))
